<script>
 import { round } from '$lib/utils/helper'; import { getTeamFromTeamManagers } from '$lib/utils/helperFunctions/universalFunctions';
 export let matchupArray=[];export let players={};export let displayWeek;export let year;export let leagueTeamManagers;
 const n=v=>Number(round(Number(v)||0)),sum=a=>(a||[]).reduce((t,v)=>t+(Number(v)||0),0);const team=id=>{try{return getTeamFromTeamManagers(leagueTeamManagers,Number(id),year)||{name:`Team ${id}`}}catch(e){return{name:`Team ${id}`}}};const proj=e=>(e?.starters||[]).reduce((t,id)=>t+(Number(players?.[id]?.wi?.[displayWeek]?.p)||0),0);
 const build=()=>{const teams=[],games=[];for(const m of matchupArray||[]){if(!m?.[0]||!m?.[1])continue;const a=m[0],b=m[1],ap=n(sum(a.points)),bp=n(sum(b.points)),at=team(a.roster_id),bt=team(b.roster_id),ar={id:a.roster_id,name:at.name,score:ap,projection:n(proj(a)),won:ap>bp,opp:bt.name,oppScore:bp},br={id:b.roster_id,name:bt.name,score:bp,projection:n(proj(b)),won:bp>ap,opp:at.name,oppScore:ap};teams.push(ar,br);games.push({a:ar,b:br,margin:n(Math.abs(ap-bp))})}if(!teams.length)return{awards:[],verdict:''};const sorted=[...teams].sort((a,b)=>b.score-a.score);for(const t of teams)t.allPlayWins=teams.filter(o=>o.id!==t.id&&t.score>o.score).length;const wins=teams.filter(t=>t.won),losses=teams.filter(t=>!t.won),awards=[];const beatdown=[...games].sort((a,b)=>b.margin-a.margin)[0];if(beatdown&&beatdown.margin>=20){const w=beatdown.a.won?beatdown.a:beatdown.b,l=beatdown.a.won?beatdown.b:beatdown.a;awards.push({label:'💥 Beatdown of the Week',text:`${w.name} buried ${l.name} by ${beatdown.margin} points, the largest margin of Week ${displayWeek}.`})}const heart=[...games].filter(g=>g.margin<=7).sort((a,b)=>a.margin-b.margin)[0];if(heart){const l=heart.a.won?heart.b:heart.a;awards.push({label:'💔 Heartbreaker',text:`${l.name} came up just ${heart.margin} points short against ${l.opp}. That's the kind of loss that sticks with you.`})}const lucky=[...wins].sort((a,b)=>a.score-b.score)[0];if(lucky)awards.push({label:'🍀 Lucky Bastard',text:`${lucky.name} won with ${lucky.score}, the lowest score among this week's winners. A win is a win.`});const robbed=[...losses].sort((a,b)=>b.allPlayWins-a.allPlayWins||b.score-a.score)[0];if(robbed&&robbed.allPlayWins>=Math.ceil((teams.length-1)*.65))awards.push({label:'🤬 Robbed',text:`${robbed.name} scored ${robbed.score} and would have beaten ${robbed.allPlayWins} of the other ${teams.length-1} teams this week. Unfortunately, ${robbed.opp} was not one of them.`});const collapse=losses.map(t=>({...t,edge:n(t.projection-(teams.find(o=>o.id!==t.id&&o.name===t.opp)?.projection||0))})).filter(t=>t.edge>=8).sort((a,b)=>b.edge-a.edge)[0];if(collapse)awards.push({label:'📉 Collapse',text:`${collapse.name} entered as roughly an ${collapse.edge}-point projected favorite and still lost to ${collapse.opp}. Brutal.`});const statement=wins.map(t=>({...t,oppAll:teams.find(o=>o.id!==t.id&&o.name===t.opp)?.allPlayWins||0})).sort((a,b)=>b.oppAll-a.oppAll)[0];if(statement&&statement.oppScore>=sorted[Math.floor(sorted.length/2)].score)awards.push({label:'👑 Statement Win',text:`${statement.name} didn't get an easy one—they beat ${statement.opp} despite ${statement.opp} posting ${statement.oppScore}. That's a statement.`});const top=sorted[0],robbedText=robbed&&robbed.allPlayWins>=Math.ceil((teams.length-1)*.65)?` Meanwhile, ${robbed.name} got the week's worst scheduling luck despite scoring ${robbed.score}.`:'';return{awards:awards.slice(0,5),verdict:`Week ${displayWeek} belonged to ${top.name}, who led the league with ${top.score} points${top.won?' and walked away with the win':' despite somehow taking a loss'}.${robbedText}`}};$: news=build();
</script>
<style>.news{width:95%;max-width:900px;margin:-12px auto 24px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.item,.verdict{padding:14px;border:1px solid var(--ccc);border-radius:14px;background:var(--fff);box-shadow:0 4px 14px rgba(0,0,0,.06)}.label{font-size:.7rem;font-weight:850;text-transform:uppercase;opacity:.62;margin-bottom:5px}.text{font-size:.86rem;line-height:1.45;font-weight:600}.verdict{margin-top:10px}.verdict .text{font-size:.92rem}@media(max-width:600px){.news{width:100%}.grid{grid-template-columns:1fr}.text{font-size:.8rem}}</style>
{#if news.awards.length||news.verdict}<section class="news"><div class="grid">{#each news.awards as a}<div class="item"><div class="label">{a.label}</div><div class="text">{a.text}</div></div>{/each}</div>{#if news.verdict}<div class="verdict"><div class="label">📰 Week {displayWeek} — GGL Newsroom Verdict</div><div class="text">{news.verdict}</div></div>{/if}</section>{/if}